// src/routes/docs/$docType/$docId.tsx
export const Route = createFileRoute('/docs/$docType/$docId')({
  validateSearch: z.object({ details: z.boolean().optional() }),
  ssr: ({ params, search }) => {
    if (params.status === 'success' && params.value.docType === 'sheet') {
      return false
    }
    if (search.status === 'success' && search.value.details) {
      return 'data-only'
    }
  },
  beforeLoad: () => {
    console.log('ssr()의 결과에 따라 서버에서 실행됨')
  },
  loader: () => {
    console.log('ssr()의 결과에 따라 서버에서 실행됨')
  },
  component: () => <div>이 컴포넌트는 클라이언트에서 렌더링돼요</div>,
})

